/** Workbook-native importer. No macros, external links or workbook formulas are executed. */
const MAX_FILE=40*1024*1024,MAX_XML=32*1024*1024;
const text=bytes=>new TextDecoder('utf-8').decode(bytes);
function xml(str){const d=new DOMParser().parseFromString(str,'application/xml');if(d.getElementsByTagName('parsererror').length)throw Error('工作簿 XML 解析失败');return d;}
function els(node,name){return [...node?.getElementsByTagName('*')||[]].filter(x=>x.localName===name);}
function direct(node,name){return [...node?.children||[]].filter(x=>x.localName===name);}
function pathResolve(base,to){let a=(to.startsWith('/')?to.slice(1):base+'/'+to).split('/'),p=[];for(const x of a){if(!x||x==='.')continue;if(x==='..')p.pop();else p.push(x);}return p.join('/');}
function excelZip(buf){const b=new Uint8Array(buf),d=new DataView(buf);let end=-1;for(let i=b.length-22;i>=Math.max(0,b.length-65558);i--)if(d.getUint32(i,true)===0x06054b50){end=i;break;}if(end<0)throw Error('文件不是有效的 Excel ZIP 工作簿');const count=d.getUint16(end+10,true),offset=d.getUint32(end+16,true);if(count>8000||count===65535)throw Error('不支持 ZIP64 或超大型文件目录');let p=offset;const files=new Map();for(let i=0;i<count;i++){if(d.getUint32(p,true)!==0x02014b50)throw Error('Excel ZIP 目录损坏');const n=d.getUint16(p+28,true),ex=d.getUint16(p+30,true),comment=d.getUint16(p+32,true),len=d.getUint32(p+24,true);const key=text(b.subarray(p+46,p+46+n)),method=d.getUint16(p+10,true),size=d.getUint32(p+20,true),local=d.getUint32(p+42,true);files.set(key,{method,size,len,local});p+=46+n+ex+comment;}return{has:key=>files.has(key),async read(key){const f=files.get(key);if(!f)throw Error('缺少工作簿文件 '+key);if(f.len>MAX_XML)throw Error('工作表 XML 超过 32 MB，需分拆后分析');const start=f.local+30+d.getUint16(f.local+26,true)+d.getUint16(f.local+28,true);if(start+f.size>b.length)throw Error('ZIP 内容不完整');const raw=b.slice(start,start+f.size);if(f.method===0)return text(raw);if(f.method!==8)throw Error('不支持当前 Excel 压缩格式');const stream=new Blob([raw]).stream().pipeThrough(new DecompressionStream('deflate-raw'));const expanded=await new Response(stream).arrayBuffer();if(expanded.byteLength>MAX_XML)throw Error('解压后工作表过大');return text(new Uint8Array(expanded));}};}
export function toCol(index){let s='';for(let n=index+1;n>0;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s;}
export function fromCol(s){if(!/^[A-Z]{1,4}$/i.test(String(s)))return -1;return [...s.toUpperCase()].reduce((n,c)=>n*26+c.charCodeAt(0)-64,0)-1;}
export function addressToIndex(ref){let m=/^\$?([A-Z]{1,4})\$?(\d+)$/i.exec(String(ref).trim());return m?{col:fromCol(m[1]),row:Number(m[2])}:null;}
const contentValue=c=>{let type=c.getAttribute('t'),v=direct(c,'v')[0]?.textContent;if(type==='inlineStr')return els(direct(c,'is')[0]||c,'t').map(n=>n.textContent).join('');if(type==='b')return v==='1';if(type==='e')return v||'#ERROR';if(v==null)return '';if(type==='str'||type==='d')return v;if(type==='n'||!type){const num=Number(v);return Number.isFinite(num)&&v.trim()!==''?num:v;}return v;};
function parseSheet(document,shared){let cells=new Map(),byRow=new Map(),formulas=0,errors=0,maxRow=1,maxCol=1,truncated=false;const data=els(document,'sheetData')[0];if(!data)return {cells,byRow,formulas,errors,maxRow,maxCol,truncated};for(const row of direct(data,'row')){for(const c of direct(row,'c')){const addr=c.getAttribute('r'),idx=addressToIndex(addr);if(!idx)continue;if(cells.size>=220000){truncated=true;break;}let v=contentValue(c);if(c.getAttribute('t')==='s'){v=shared[Number(direct(c,'v')[0]?.textContent)]??'';}const f=direct(c,'f')[0];if(f)formulas++;if(c.getAttribute('t')==='e')errors++;if(v===''&&!f)continue;const rec={a:addr,row:idx.row,col:idx.col,v,f:f?(f.textContent||''):'',ft:f?.getAttribute('t')||'',type:c.getAttribute('t')||'n'};cells.set(addr.toUpperCase(),rec);if(!byRow.has(idx.row))byRow.set(idx.row,[]);byRow.get(idx.row).push(rec);maxRow=Math.max(maxRow,idx.row);maxCol=Math.max(maxCol,idx.col+1);}if(truncated)break;}
return {cells,byRow,formulas,errors,maxRow,maxCol,truncated};}
export function cellAt(sheet,ref){return sheet?.cells.get(String(ref).replaceAll('$','').toUpperCase())||null;}
export async function openWorkbook(file){if(!file||!file.name.match(/\.xlsx$|\.xlsm$/i))throw Error('请选择 .xlsx 或 .xlsm 文件');if(file.size>MAX_FILE)throw Error('工作簿超过 40MB，请先压缩或拆分');const zip=excelZip(await file.arrayBuffer());const wb=xml(await zip.read('xl/workbook.xml')),rels=xml(await zip.read('xl/_rels/workbook.xml.rels'));const links=new Map(els(rels,'Relationship').map(r=>[r.getAttribute('Id'),pathResolve('xl',r.getAttribute('Target')||'')]));const source=els(wb,'sheet');const sheets=source.map((s,i)=>({id:i,name:s.getAttribute('name')||`Sheet${i+1}`,rel:s.getAttribute('r:id')||s.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id'),status:s.getAttribute('state')||'visible'})).map(s=>({...s,path:links.get(s.rel)}));let shared=[];if(zip.has('xl/sharedStrings.xml')){const t=xml(await zip.read('xl/sharedStrings.xml'));shared=els(t,'si').map(n=>els(n,'t').map(t=>t.textContent||'').join(''));}const defined=els(wb,'definedName').map(n=>({name:n.getAttribute('name'),ref:(n.textContent||'').slice(0,220)}));const cache=new Map();return {name:file.name,size:file.size,isMacro:file.name.toLowerCase().endsWith('.xlsm'),sheets,defined,sharedCount:shared.length,async load(name){const chosen=sheets.find(s=>s.name===name);if(!chosen)throw Error('找不到工作表：'+name);if(cache.has(name))return cache.get(name);if(!chosen.path||!zip.has(chosen.path))throw Error('无法读取工作表：'+name);const parsed=parseSheet(xml(await zip.read(chosen.path)),shared);if(cache.size>=2)cache.delete(cache.keys().next().value);cache.set(name,parsed);return parsed;},clear(){cache.clear();}};}
export function findCellCandidates(sheet,max=120){const result=[];for(const [row,entries] of sheet.byRow){for(const c of entries){if(typeof c.v!=='number'||c.f)continue;const previous=cellAt(sheet,toCol(c.col-1)+(row));const upper=cellAt(sheet,toCol(c.col)+(row-1));const label=[previous?.v,upper?.v].find(x=>typeof x==='string'&&x.trim().length>1&&x.trim().length<65);if(label){result.push({cell:c.a,label,value:c.v});if(result.length>=max)return result;}}}return result;}
export function curve(sheet,xcol,ycol,start,end,maxPoints=400){const output=[],xc=fromCol(xcol),yc=fromCol(ycol);if(xc<0||yc<0)return [];for(let row=Math.max(1,start);row<=Math.min(end,15000);row++){let x=cellAt(sheet,toCol(xc)+row)?.v,y=cellAt(sheet,toCol(yc)+row)?.v;if(typeof x==='number'&&Number.isFinite(x)&&typeof y==='number'&&Number.isFinite(y))output.push({row,x,y});}if(output.length>maxPoints){const step=Math.ceil(output.length/maxPoints);return output.filter((_,i)=>i%step===0||i===output.length-1);}return output;}
export function diffSheets(a,b,limit=1000){const diffs=[];let count=0;for(const [addr,c] of a.cells){const d=b.cells.get(addr);if(!d){count++;if(diffs.length<limit)diffs.push({address:addr,a:c.v,b:'',formulaChanged:!!c.f});continue;}if(String(c.v)!==String(d.v)||c.f!==d.f){count++;if(diffs.length<limit)diffs.push({address:addr,a:c.v,b:d.v,formulaChanged:c.f!==d.f});}}for(const [addr,c] of b.cells)if(!a.cells.has(addr)){count++;if(diffs.length<limit)diffs.push({address:addr,a:'',b:c.v,formulaChanged:!!c.f});}return{total:count,rows:diffs};}

/** Exact cached-series diagnostics: highlights candidate anomalies, not confirmed game-design defects. */
export function analyzeSeries(points){
  if(points.length<3)return {issues:[],summary:'有效样本过少，至少需要 3 个点'};
  const step=points.slice(1).map((p,i)=>({row:p.row,delta:p.y-points[i].y,x:p.x}));
  const absolute=step.map(i=>Math.abs(i.delta)).filter(v=>v>0).sort((a,b)=>a-b);
  const median=absolute.length?absolute[Math.floor(absolute.length/2)]:0;
  const issues=[];
  for(const d of step){
    if(d.delta<0)issues.push({row:d.row,level:'关注',description:`数值下降 ${Math.abs(d.delta).toFixed(3)}（需核对是否为设计预期）`});
    if(median>0&&Math.abs(d.delta)>median*5)issues.push({row:d.row,level:'突变',description:`相邻样本变化 ${d.delta.toFixed(3)}，超过典型变化绝对值 ${median.toFixed(3)} 的 5 倍`});
  }
  let streak=0;for(const d of step){if(d.delta===0)streak++;else streak=0;if(streak===5)issues.push({row:d.row,level:'平台期',description:'连续 5 个样本数值未变化，建议确认是否为预期解锁节奏'});}
  return{issues:issues.slice(0,80),summary:`${points.length} 个样本；发现 ${issues.length} 条需复核的异常候选（不代表真实 BUG）`};
}
